problems.solution:
def shoelace(pts):
    s = 0
    for (x1, y1), (x2, y2) in zip(pts, pts[1:] + pts[:1]):
        s += x1 * y2 - x2 * y1
    return s / 2

def apply(m, p):
    (a, b), (c, d) = m
    x, y = p
    return (a * x + b * y, c * x + d * y)

def area_factor(m, pts):
    new = [apply(m, p) for p in pts]
    return shoelace(new) / shoelace(pts)

import numpy as np

def is_invertible(M, tol=1e-9):
    return bool(abs(np.linalg.det(M)) > tol)
